package org.slavicmyths.audit;
import java.nio.file.*;import java.io.*;import java.lang.management.ManagementFactory;import jdk.jfr.*;
import net.minecraft.client.Minecraft;import net.minecraft.client.gui.screens.TitleScreen;import net.minecraft.core.registries.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.level.*;import net.minecraft.world.level.levelgen.*;import net.minecraft.world.level.levelgen.presets.WorldPresets;import net.minecraft.world.entity.*;import net.minecraft.world.item.*;import net.minecraft.world.InteractionHand;import net.minecraft.world.Difficulty;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.event.*;import net.neoforged.neoforge.event.tick.ServerTickEvent;
/** Test-only scripted full native boss lifecycle on ground. Not Survival balance or ritual-route acceptance. */
@EventBusSubscriber(modid="slavicmyths",value=Dist.CLIENT)
public final class FocusedProbe {
 static final String[] NAMES={"poloz_cycle","gorynych_cycle","karachun_cycle","morozko_cycle","post_cleanup"};
 static final Path OUT=Path.of(System.getProperty("audit.output"));static PrintWriter events,ticks,frames,combat;static Recording rec;
 static volatile int scene=-1,age,phaseSignal=-1;static volatile boolean done;static boolean opened,ready;static LivingEntity actor;static long pre,lastTick,lastFrame;static String lastShot="";static int bootstrap;
 static void init()throws Exception{Files.createDirectories(OUT);events=new PrintWriter(Files.newBufferedWriter(OUT.resolve("events.txt")));ticks=new PrintWriter(Files.newBufferedWriter(OUT.resolve("ticks.csv")));frames=new PrintWriter(Files.newBufferedWriter(OUT.resolve("frames.csv")));combat=new PrintWriter(Files.newBufferedWriter(OUT.resolve("combat.csv")));ticks.println("scene,repeat,age,ms,interval_ns,heap_bytes,entities,loaded_chunks,gc_count,gc_ms");frames.println("scene,repeat,age,frame_ms");combat.println("scene,age,alive,removed,hp,phase,action,target_player,player_y");rec=new Recording(Configuration.getConfiguration("profile"));rec.setMaxSize(128L*1024*1024);rec.start();}
 @SubscribeEvent public static void client(ClientTickEvent.Post e){var m=Minecraft.getInstance();if(!opened&&m.screen instanceof TitleScreen){opened=true;try{init();}catch(Exception ex){throw new RuntimeException(ex);}m.options.pauseOnLostFocus=false;m.options.renderDistance().set(8);m.options.simulationDistance().set(5);m.options.framerateLimit().set(260);m.options.enableVsync().set(false);m.options.tutorialStep=net.minecraft.client.tutorial.TutorialSteps.NONE;m.options.save();events.println("ACTIVE_OPTIONS rd=8 sim=5 vsync=false fpsLimit=260 WINDOW="+m.getWindow().getWidth()+"x"+m.getWindow().getHeight()+" GPU="+com.mojang.blaze3d.platform.GlUtil.getRenderer());events.flush();m.createWorldOpenFlows().createFreshLevel("PerfGround-"+System.currentTimeMillis(),new LevelSettings("Perf ground",GameType.SURVIVAL,false,Difficulty.NORMAL,true,new GameRules(),WorldDataConfiguration.DEFAULT),new WorldOptions(280015,false,false),r->r.registryOrThrow(Registries.WORLD_PRESET).getHolderOrThrow(WorldPresets.FLAT).value().createWorldDimensions(),m.screen);}if(done){done=false;m.stop();}}
 @SubscribeEvent public static void before(ServerTickEvent.Pre e){pre=System.nanoTime();if(!ready||scene<0||scene>=NAMES.length||actor==null)return;var s=e.getServer();if(s.getPlayerList().getPlayers().isEmpty())return;var p=s.getPlayerList().getPlayers().getFirst();var w=p.serverLevel();if(!p.isAlive()||p.getY()<w.getMinBuildHeight()){finish("INVALID_FIXTURE player_dead_or_void");return;}
  if(age>200&&age%40==0&&actor.isAlive()){
   if(actor instanceof org.slavicmyths.gorynych.Gorynych g){if(g.state()<org.slavicmyths.gorynych.GorynychRules.EXHAUSTED){float before=g.logicalHealth();boolean hit=g.hurt(p.damageSources().playerAttack(p),100);events.println("HIT "+NAMES[scene]+" age="+age+" accepted="+hit+" before="+before+" after="+g.logicalHealth());}
    else if(g.state()==org.slavicmyths.gorynych.GorynychRules.EXHAUSTED||g.state()==org.slavicmyths.gorynych.GorynychRules.CLEANSING){for(int h=0;h<3;h++)if((g.cleanMask()&(1<<h))==0){var head=g.parts[h];p.teleportTo(w,head.getX(),-60,head.getZ()-1,0,0);Item item=h==0?org.slavicmyths.quest185.Quest185Content.POWDER.get():org.slavicmyths.sanctuary.SanctuaryContent.ITEMS.get(h==1?"purifying_ash":"purified_water_bottle").get();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(item));var result=g.cleanse(p,InteractionHand.MAIN_HAND,h);events.println("CLEANSE head="+h+" result="+result+" mask="+g.cleanMask());}}}
   else if(actor instanceof org.slavicmyths.karachun.Karachun b){if(b.fighting()){float before=b.getHealth();boolean hit=b.hurt(p.damageSources().playerAttack(p),100);events.println("HIT "+NAMES[scene]+" age="+age+" accepted="+hit+" before="+before+" after="+b.getHealth());}}
   else if(actor instanceof org.slavicmyths.morozko.Morozko b){if(b.fighting()){float before=b.getHealth();boolean hit=b.hurt(p.damageSources().playerAttack(p),100);events.println("HIT "+NAMES[scene]+" age="+age+" accepted="+hit+" before="+before+" after="+b.getHealth());}}
   else{float before=actor.getHealth();boolean hit=actor.hurt(p.damageSources().playerAttack(p),100);events.println("HIT "+NAMES[scene]+" age="+age+" accepted="+hit+" before="+before+" after="+actor.getHealth());}events.flush();}
 }
 static int phase(){return actor instanceof org.slavicmyths.poloz.GreatPoloz b?b.phase():actor instanceof org.slavicmyths.gorynych.Gorynych b?b.state():actor instanceof org.slavicmyths.karachun.Karachun b?b.phase():actor instanceof org.slavicmyths.morozko.Morozko b?b.phase():-1;}
 static int action(){return actor instanceof org.slavicmyths.poloz.GreatPoloz b?b.action():actor instanceof org.slavicmyths.gorynych.Gorynych b?b.bodyAction():actor instanceof org.slavicmyths.karachun.Karachun b?b.action():actor instanceof org.slavicmyths.morozko.Morozko b?b.action():-1;}
 static float hp(){return actor instanceof org.slavicmyths.gorynych.Gorynych b?b.logicalHealth():actor==null?0:actor.getHealth();}
 @SubscribeEvent public static void after(ServerTickEvent.Post e){if(ticks==null||done||scene>=NAMES.length)return;long n=System.nanoTime(),elapsed=n-pre,interval=lastTick==0?0:n-lastTick;lastTick=n;var s=e.getServer();if(s.getPlayerList().getPlayers().isEmpty())return;var w=s.overworld();var p=s.getPlayerList().getPlayers().getFirst();if(!ready){if(++bootstrap<100)return;ready=true;w.getGameRules().getRule(GameRules.RULE_DOMOBSPAWNING).set(false,s);w.getGameRules().getRule(GameRules.RULE_DAYLIGHT).set(false,s);w.setDayTime(6000);scene=0;setup(w,p);return;}age++;phaseSignal=phase();if(actor!=null){combat.println(NAMES[scene]+","+age+","+actor.isAlive()+","+actor.isRemoved()+","+hp()+","+phase()+","+action()+","+(actor instanceof Mob m&&m.getTarget()==p)+","+p.getY());if(age%20==0){events.println("BOSS_STATE "+NAMES[scene]+" age="+age+" target="+(actor instanceof Mob m&&m.getTarget()==p)+" phase="+phase()+" action="+action()+" hp="+hp());events.flush();}}
  if(age>200){long gc=0,gcms=0;for(var b:ManagementFactory.getGarbageCollectorMXBeans()){gc+=b.getCollectionCount();gcms+=b.getCollectionTime();}var rt=Runtime.getRuntime();int entities=0;for(var a:w.getAllEntities())entities++;ticks.println(NAMES[scene]+",0,"+age+","+elapsed/1e6+","+interval+","+(rt.totalMemory()-rt.freeMemory())+","+entities+","+w.getChunkSource().getLoadedChunksCount()+","+gc+","+gcms);}
  if(age>=2000||(scene==4&&age>=600)){events.println("END_CYCLE "+NAMES[scene]+" alive="+(actor!=null&&actor.isAlive())+" removed="+(actor!=null&&actor.isRemoved())+" phase="+phase()+" hp="+hp());for(var stack:p.getInventory().items)if(!stack.isEmpty())events.println("INVENTORY "+NAMES[scene]+" "+BuiltInRegistries.ITEM.getKey(stack.getItem())+" x"+stack.getCount());for(var a:w.getAllEntities())if(a instanceof net.minecraft.world.entity.item.ItemEntity item)events.println("LOOT_ENTITY "+NAMES[scene]+" "+BuiltInRegistries.ITEM.getKey(item.getItem().getItem())+" x"+item.getItem().getCount());ticks.flush();frames.flush();combat.flush();events.flush();age=0;if(++scene>=NAMES.length){finish("COMPLETE");return;}setup(w,p);}
 }
 static void setup(net.minecraft.server.level.ServerLevel w,net.minecraft.server.level.ServerPlayer p){if(org.slavicmyths.poloz.PolozEvent.get(w).running())org.slavicmyths.poloz.PolozEvent.get(w).finish(w,false);var old=new java.util.ArrayList<Entity>();w.getAllEntities().forEach(a->{if(!(a instanceof net.minecraft.world.entity.player.Player))old.add(a);});for(var a:old){if(a instanceof org.slavicmyths.gorynych.Gorynych b)b.cancelPeacefully();else if(a instanceof org.slavicmyths.karachun.Karachun b)b.cancelPeacefully();else if(a instanceof org.slavicmyths.morozko.Morozko b)b.cancelPeacefully();else a.discard();}p.teleportTo(w,0,-60,-12,0,0);p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);p.fallDistance=0;p.setInvulnerable(false);p.setNoGravity(false);p.setHealth(20);p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.DAMAGE_RESISTANCE,100000,4));p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);actor=null;if(scene<4){String id=switch(scene){case 0->"great_poloz";case 1->"zmey_gorynych";case 2->"karachun";default->"morozko";};actor=(LivingEntity)BuiltInRegistries.ENTITY_TYPE.get(ResourceLocation.fromNamespaceAndPath("slavicmyths",id)).create(w);actor.moveTo(0,-60,-4,180,0);if(actor instanceof org.slavicmyths.poloz.GreatPoloz b)b.initializeBody();if(actor instanceof org.slavicmyths.karachun.Karachun b){b.session=java.util.UUID.randomUUID();b.owner=p.getUUID();b.anchor=p.position();b.configureHealth(1600);org.slavicmyths.karachun.NightLedger.get(w).session(b.session).putUUID("Owner",p.getUUID());}if(actor instanceof org.slavicmyths.morozko.Morozko b){b.session=java.util.UUID.randomUUID();b.owner=p.getUUID();b.anchor=p.position();org.slavicmyths.morozko.FrostLedger.get(w).session(b.session).putUUID("Owner",p.getUUID());}if(!w.addFreshEntity(actor))throw new IllegalStateException("Actor rejected");((Mob)actor).setTarget(p);}events.println("SCENE "+NAMES[scene]+" repeat=0 time="+System.currentTimeMillis());events.flush();}
 static void finish(String reason){if(done)return;events.println(reason);events.flush();ticks.flush();frames.flush();combat.flush();try{rec.stop();rec.dump(OUT.resolve("profile.jfr"));rec.close();}catch(Exception ex){throw new RuntimeException(ex);}scene=NAMES.length;done=true;}
 @SubscribeEvent public static void render(RenderFrameEvent.Post e){long n=System.nanoTime();if(ready&&scene>=0&&scene<NAMES.length&&age>200&&Minecraft.getInstance().level!=null){frames.println(NAMES[scene]+",0,"+age+","+(lastFrame==0?0:(n-lastFrame)/1e6));String key=NAMES[scene]+"-phase"+phaseSignal;if(scene<4&&!key.equals(lastShot)){lastShot=key;var m=Minecraft.getInstance();try(var im=net.minecraft.client.Screenshot.takeScreenshot(m.getMainRenderTarget())){im.writeToFile(OUT.resolve(key+".png"));}catch(Exception ex){throw new RuntimeException(ex);}}}lastFrame=n;}
}
